Function next <- PlusOne(x As Integer)
  Define next As Integer;
  next <- x + 1;
EndFunction

Function applied <- ApplyTwice(f As Function(Integer) As Integer, x As Integer)
  Define applied As Integer;
  applied <- f(f(x));
EndFunction

Algorithm Twice
  Write ApplyTwice(PlusOne, 5);
EndAlgorithm

Function next <- PlusOne(x As Integer)
  Define next As Integer;
  next <- x + 1;
EndFunction

Function cheap <- IsCheap(price As Integer)
  Define cheap As Boolean;
  cheap <- price <= 2;
EndFunction

Function total <- Sum(a As Integer, b As Integer)
  Define total As Integer;
  total <- a + b;
EndFunction

Function mapped <- Map(v As Vector<Integer>, f As Function(Integer) As Integer)
  Define mapped As Vector<Integer> <- vector();
  For Each elemento In v Do
    mapped.append(f(elemento));
  EndFor
EndFunction

Function chosen <- Filter(v As Vector<Integer>, condition As Function(Integer) As Boolean)
  Define chosen As Vector<Integer> <- vector();
  For Each elemento In v Do
    If condition(elemento) Then
      chosen.append(elemento);
    EndIf
  EndFor
EndFunction

Function accumulated <- Reduce(v As Vector<Integer>, f As Function(Integer, Integer) As Integer, initial As Integer)
  Define accumulated As Integer <- initial;
  For Each elemento In v Do
    accumulated <- f(accumulated, elemento);
  EndFor
EndFunction

Algorithm Prices
  Define prices As Vector<Integer> <- vector();
  prices.append(3);
  prices.append(5);
  prices.append(2);
  prices.append(1);
  prices.append(2);
  Write Map(prices, PlusOne);
  Write Filter(prices, IsCheap);
  Write Reduce(prices, Sum, 0);
EndAlgorithm
